package com.witchersbestiary.fist;
import net.minecraft.entity.*;import net.minecraft.entity.attribute.*;import net.minecraft.registry.*;import net.minecraft.util.Identifier;
public final class FistRegistry{
 public static final EntityType<FistNpc> NOVICE=register("novice_fighter",0),EXPERIENCED=register("experienced_fighter",1),CHAMPION=register("champion_fighter",2);
 private static EntityType<FistNpc> register(String id,int tier){return Registry.register(Registries.ENTITY_TYPE,Identifier.of("witchersbestiary",id),EntityType.Builder.<FistNpc>create((type,w)->new FistNpc(type,w,tier),SpawnGroup.CREATURE).dimensions(.65f,1.9f).maxTrackingRange(8).build("witchersbestiary:"+id));}
 public static final EntityType<RockTrollEntity> ROCK_TROLL=Registry.register(Registries.ENTITY_TYPE,Identifier.of("witchersbestiary","rock_troll"),EntityType.Builder.<RockTrollEntity>create(RockTrollEntity::new,SpawnGroup.CREATURE).dimensions(1.7f,2.8f).maxTrackingRange(10).build("witchersbestiary:rock_troll"));
 public static void initialize(){RockTrollSpawns.initialize();net.fabricmc.fabric.api.object.builder.v1.entity.FabricDefaultAttributeRegistry.register(ROCK_TROLL,net.minecraft.entity.mob.MobEntity.createMobAttributes().add(EntityAttributes.GENERIC_MAX_HEALTH,140).add(EntityAttributes.GENERIC_MOVEMENT_SPEED,.25).add(EntityAttributes.GENERIC_FOLLOW_RANGE,32).add(EntityAttributes.GENERIC_KNOCKBACK_RESISTANCE,.8));var trollEgg=Registry.register(Registries.ITEM,Identifier.of("witchersbestiary","rock_troll_spawn_egg"),new net.minecraft.item.SpawnEggItem(ROCK_TROLL,0x65655e,0x526344,new net.minecraft.item.Item.Settings()));net.fabricmc.fabric.api.itemgroup.v1.ItemGroupEvents.modifyEntriesEvent(net.minecraft.item.ItemGroups.SPAWN_EGGS).register(e->e.add(trollEgg));for(var type:java.util.List.of(NOVICE,EXPERIENCED,CHAMPION)){net.fabricmc.fabric.api.object.builder.v1.entity.FabricDefaultAttributeRegistry.register(type,net.minecraft.entity.mob.MobEntity.createMobAttributes().add(EntityAttributes.GENERIC_MAX_HEALTH,40).add(EntityAttributes.GENERIC_MOVEMENT_SPEED,.28).add(EntityAttributes.GENERIC_FOLLOW_RANGE,24));var id=Registries.ENTITY_TYPE.getId(type);var egg=Registry.register(Registries.ITEM,Identifier.of("witchersbestiary",id.getPath()+"_spawn_egg"),new net.minecraft.item.SpawnEggItem(type,0x69482f,0xe0c49d,new net.minecraft.item.Item.Settings()));net.fabricmc.fabric.api.itemgroup.v1.ItemGroupEvents.modifyEntriesEvent(net.minecraft.item.ItemGroups.SPAWN_EGGS).register(e->e.add(egg));}}
}
